import {useDataStore} from "@/src/store";

defineOptions({
    name: "PostBar",
});

const emit = defineEmits<{
    focusPost: [postId: PostId];
    highlightPost: [postId: PostId];
    unhighlightPost: [postId: PostId];
}>();

///// refs and variables /////
const dataStore = useDataStore();
